func TestRedactSensitiveValues(t *testing.T) {
	ctx := context.WithValue(context.Background(), sensitiveValuesKey{}, []string{`s3cr/et "value"`, "abc", "s3cr"})
	input := strings.Join([]string{
		`raw=s3cr/et "value"`,
		"query=" + url.QueryEscape(`s3cr/et "value"`),
		"path=/" + url.PathEscape(`s3cr/et "value"`),
		`json={"password":"s3cr/et \"value\""}`,
		"short=abc",
	}, "\n")

	want := strings.Join([]string{
		"raw=(sensitive)",
		"query=(sensitive)",
		"path=/(sensitive)",
		`json={"password":"(sensitive)"}`,
		"short=abc",
	}, "\n")
	if got := redactSensitiveValues(ctx, input); got != want {
		t.Errorf("redactSensitiveValues returned\n%s\nwant\n%s", got, want)
	}
}

